package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Diagnoses a user-requested original archive without changing reader preferences. */
public class VoiceArchiveDiagnosticTest extends VoiceWarmupTest {
    String name;public void onCreate(Bundle args){name=args==null?"":args.getString("file","");super.onCreate(args);}
    public void onStart(){Bundle result=new Bundle();boolean success=false;VoicePackages store=VoicePackages.get(getTargetContext());PackageSpeaker[] speaker={null};try{check(!name.isEmpty()&&!name.contains("/")&&!name.contains("\\"),"Invalid diagnostic filename");check(!store.busy,"Another import is active");File source=new File(getTargetContext().getExternalFilesDir(null),name);check(source.isFile(),"Archive missing");result.putString("runtime",com.k2fsa.sherpa.onnx.VersionInfo.Companion.getVersion());store.importUri("",Uri.fromFile(source));await(()->!store.busy,"Import timed out: "+store.phase,150000);result.putString("phase",store.phase);result.putString("code",store.error);if(store.lastFailure!=null)result.putString("detail",android.util.Log.getStackTraceString(store.lastFailure));VoiceModel model=store.models.get(store.lastInstalled);if(model==null&&store.error.equals("duplicate")){String title=name.replaceFirst("(?i)\\.(tar\\.bz2|tar\\.gz|tgz|zip|tar)$","");for(VoiceModel pack:store.all())if(pack.name.equals(title))model=pack;}check(model!=null,"Import failed: "+store.error);result.putString("model",model.json().toString());if(model.type.equals("kokoro")){check(model.supports("zh")&&model.supports("en"),"Kokoro languages missing");check(model.speakers==54&&model.speakerNames.size()==54&&model.lexicons.size()>=2,"Kokoro voice/lexicon metadata missing");check(model.defaultSpeaker("zh")==45,"Wrong Chinese default speaker");VoiceModel reopened=VoiceModel.read(model.directory);check(reopened.voices.equals(model.voices)&&reopened.speakerNames.equals(model.speakerNames)&&reopened.lexicons.equals(model.lexicons),"Kokoro metadata did not persist");}CountDownLatch init=new CountDownLatch(1),done=new CountDownLatch(1);AtomicReference<Throwable> failure=new AtomicReference<>();PackageSpeaker nativeSpeaker=new PackageSpeaker(getTargetContext(),new VoicePackages.Selection(model,model.defaultSpeaker("zh")),"zh");speaker[0]=nativeSpeaker;nativeSpeaker.init(error->{failure.set(error);init.countDown();});check(init.await(40,TimeUnit.SECONDS)&&failure.get()==null,"Playback model failed: "+failure.get());AtomicInteger count=new AtomicInteger();nativeSpeaker.speakSequence(Arrays.asList("你好，欢迎使用我爱听书。","这是一段连续朗读测试，确认语音包可以正常使用。"),0,1.2f,new OfflineSpeaker.SequenceListener(){public void buffering(int ready){}public void sentence(int index){count.incrementAndGet();}public void done(){done.countDown();}public void failed(Throwable error){failure.set(error);done.countDown();}});check(done.await(45,TimeUnit.SECONDS)&&failure.get()==null&&count.get()==2,"Continuous speech failed: "+failure.get());nativeSpeaker.close();speaker[0]=null;
 if(model.type.equals("kokoro")){CountDownLatch englishInit=new CountDownLatch(1),englishDone=new CountDownLatch(1);PackageSpeaker english=new PackageSpeaker(getTargetContext(),new VoicePackages.Selection(model,0),"en");speaker[0]=english;english.init(error->{failure.set(error);englishInit.countDown();});check(englishInit.await(40,TimeUnit.SECONDS)&&failure.get()==null,"English model initialization failed");english.speak("Hello, welcome to our audiobook reader. This is an English voice preview.",0,1.2f,new OfflineSpeaker.Listener(){public void started(){}public void done(){englishDone.countDown();}public void failed(Throwable error){failure.set(error);englishDone.countDown();}});check(englishDone.await(40,TimeUnit.SECONDS)&&failure.get()==null,"English preview failed");english.close();speaker[0]=null;}
 result.putString("result","PASS: original archive imported, native probe and two continuous sentences succeeded; valid requested model retained; reader preferences unchanged");success=true;}catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(speaker[0]!=null)speaker[0].close();}finish(success?-1:0,result);}
}
